Here is the commit message:
pinctrl: pinconf-generic: Fully validate 'pinmux' property

The pinconf_generic_parse_dt_pinmux() assumes that the 'pinmux' property
is not empty when present. This might be not true. With that, the allocator
will give a special value in return and not NULL which lead to the crash
when trying to access that (invalid) memory. Fix that by fully validating
'pinmux' value, including its length.

Fixes: 7112c05fff83 ("pinctrl: pinconf-generic: Add API for pinmux propertity in DTS file")
Signed-off-by: Andy Shevchenko <andriy.shevchenko@linux.intel.com>
Signed-off-by: Linus Walleij <linusw@kernel.org>

Here is the root cause:
The function `pinconf_generic_parse_dt_pinmux()` did not validate that the 'pinmux' property contains at least one entry. When the property exists but is empty (length zero), `prop->length / sizeof(u32)` gives zero, and `devm_kcalloc` with zero size may return a non-NULL pointer (special value). Later, code accesses that pointer as an array, causing a crash due to invalid memory access. The fix adds an explicit check for `npins_t == 0` and returns `-ENODATA` to prevent the invalid allocation and subsequent dereference.

Here is the patch:
  */
 int pinconf_generic_parse_dt_pinmux(struct device_node *np, struct device *dev,
 				    unsigned int **pid, unsigned int **pmux,
 				    unsigned int *npins)
 {
 	unsigned int *pid_t;
 	unsigned int *pmux_t;
 	struct property *prop;
 	unsigned int npins_t, i;
 	u32 value;
 	int ret;

 	prop = of_find_property(np, "pinmux", NULL);
 	if (!prop) {
 		dev_info(dev, "Missing pinmux property\n");
 		return -ENOENT;
 	}

+	npins_t = prop->length / sizeof(u32);
+	if (npins_t == 0) {
+		dev_info(dev, "pinmux property doesn't have entries\n");
+		return -ENODATA;
+	}
+
 	if (!pid || !pmux || !npins) {
 		dev_err(dev, "parameters error\n");
 		return -EINVAL;
 	}

-	npins_t = prop->length / sizeof(u32);
 	pid_t = devm_kcalloc(dev, npins_t, sizeof(*pid_t), GFP_KERNEL);
 	pmux_t = devm_kcalloc(dev, npins_t, sizeof(*pmux_t), GFP_KERNEL);
 	if (!pid_t || !pmux_t) {
 		dev_err(dev, "kalloc memory fail\n");
 		return -ENOMEM;
 	}
 	for (i = 0; i < npins_t; i++) {
 		ret = of_property_read_u32_index(np, "pinmux", i, &value);
 		if (ret) {
 			dev_err(dev, "get pinmux value fail\n");
 			goto exit;
 		}
 		pmux_t[i] = value & 0xff;
 		pid_t[i] = (value >> 8) & 0xffffff;
 	}
 	*pid = pid_t;
 	*pmux = pmux_t;
 	*npins = npins_t;

 	return 0;
 exit:
 	devm_kfree(dev, pid_t);
 	devm_kfree(dev, pmux_t);
 	return ret;
 }
 EXPORT_SYMBOL_GPL(pinconf_generic_parse_dt_pinmux);


